sourceReview.productInformationExcerpt:
{%- comment -%}
  22.09.2026 (LuxeStyle): Sterne im Google-Suchergebnis. Shopifys `structured_data` kennt die
  Judge.me-Metafelder nicht — GEMESSEN: 1'541 aktive Produkte mit 8'066 Bewertungen, keines mit
  aggregateRating. Wir lassen Shopifys Ausgabe unveraendert und haengen NUR bei Produkten mit
  Bewertungen (reviews.rating_count > 0) ein AggregateRating an — ueber replace_first auf dem
  einzigen `"@type":"Product",` (Brand/Offer tragen andere @type). Google verlangt dafuer echte,
  sichtbare Bewertungen auf der Seite: das Judge.me-Widget steht darunter.
{%- endcomment -%}
{%- capture luxe_sd -%}{{ closest.product | structured_data }}{%- endcapture -%}
{%- if closest.product.id == 15450856292737 -%}
  {%- for luxe_schema_variant in closest.product.variants -%}
    {%- if luxe_schema_variant.sku contains ' ' -%}
      {%- capture luxe_schema_invalid_sku -%},"sku":{{ luxe_schema_variant.sku | json }}{%- endcapture -%}
      {%- assign luxe_sd = luxe_sd | remove: luxe_schema_invalid_sku -%}
    {%- endif -%}
  {%- endfor -%}
{%- endif -%}
{%- assign luxe_rc = closest.product.metafields.reviews.rating_count.value | plus: 0 -%}
{%- assign luxe_r = closest.product.metafields.reviews.rating.value -%}
{%- if luxe_rc > 0 and luxe_r.rating -%}
  {%- capture luxe_ar -%}"@type":"Product","aggregateRating":{"@type":"AggregateRating","ratingValue":"{{ luxe_r.rating }}","bestRating":"{{ luxe_r.scale_max }}","worstRating":"{{ luxe_r.scale_min }}","ratingCount":"{{ luxe_rc }}","reviewCount":"{{ luxe_rc }}"},{%- endcapture -%}
  {%- assign luxe_sd = luxe_sd | replace_first: '"@type":"Product",', luxe_ar -%}
{%- endif -%}
<script type="application/ld+json">
  {{ luxe_sd }}
</script>
